    if(!group?.enabled||group.membership_status!=='JOINED')fail('群组已停用或尚未确认加入');
    if(!settings.enabled||!settings.global_enabled||!settings.account_enabled||!group.proactive_engagement_enabled)fail('GLOBAL、ACCOUNT 或 GROUP 开关已关闭');
    if(account.session_health!=='HEALTHY')fail('Facebook 登录身份未处于已核验健康状态');
