    if(post.fact_status==='REQUIRED'||post.fact_status==='UNVERIFIED')fail('事实敏感回复尚未可靠核验');
    let decision=post.proposed_action;
    if(decision.includes('LIKE')&&!settings.auto_like)decision=decision==='LIKE_AND_REPLY'?'REPLY_ONLY':'SKIP';
    if(decision.includes('REPLY')&&!settings.auto_reply)decision=decision==='LIKE_AND_REPLY'?'LIKE_ONLY':'SKIP';
    if(decision==='SKIP')fail('当前自动开关没有允许的动作');
    if(decision.includes('REPLY')&&!String(replyBody||'').trim())fail('回复动作需要已审核生成的原语言回复文本');
    if(decision.includes('REPLY')&&needsThemeEvidence(replyBody)&&post.fact_status!=='VERIFIED')fail('回复稿需要独立事实证据，不能发送');
    const target=facebookPostTarget(post.permalink,{externalId:post.external_id||'',groupUrl:verifiedProactiveGroupUrl(group)});if(expected?.scope_hash&&expected.scope_hash!==this.proactiveScopeHash(workspace,postId,replyBody))fail('准备期间目标、actor 或来源正文已变化，未提交');
