    const kinds=(decision==='LIKE_AND_REPLY'?['LIKE','INITIAL_REPLY']:decision==='LIKE_ONLY'?['LIKE']:['INITIAL_REPLY']).filter(kind=>!existing.some(a=>a.action_type===kind&&a.state==='CONFIRMED'));
    if(!kinds.length)fail('这些动作已经完成，不能重复执行');
    const scopedAttempt=beforeClaim?.();
