    const previous=this.db.prepare('SELECT * FROM engagement_daily_slots WHERE account_id=? AND group_id=? AND post_id=? AND day=?').get(post.account_id,post.group_id,post.id,day);
    const used=this.db.prepare("SELECT count(*) n FROM engagement_daily_slots WHERE workspace=? AND account_id=? AND group_id=? AND day=? AND state IN ('RESERVED','CONSUMED')").get(workspace,post.account_id,post.group_id,day).n;
    if(used-(previous&&previous.state!=='RELEASED'?1:0)>=settings.daily_limit)fail('该群组今日主动互动额度已用完');
    this.db.prepare("INSERT INTO engagement_daily_slots VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(account_id,group_id,post_id,day) DO UPDATE SET state=CASE WHEN engagement_daily_slots.state='CONSUMED' THEN 'CONSUMED' ELSE 'RESERVED' END,reserved_at=excluded.reserved_at").run(workspace,post.account_id,post.group_id,post.id,day,'RESERVED',time,null);
