  finishProactiveAction(workspace,actionId,evidence){return this.tx(()=>{const action=this.proactiveAction(workspace,actionId),post=this.proactivePost(workspace,action.post_id);if(action.state!=='ATTEMPTING')fail('动作不在可完成状态');if(!evidence?.readback_verified)fail('缺少独立回读，不能标记成功');const time=new Date().toISOString();this.interactionBudget?.finish('proactive:'+action.id,'CONSUMED');this.db.prepare("UPDATE engagement_actions SET state='CONFIRMED',evidence_json=?,updated_at=? WHERE id=?").run(JSON.stringify(evidence),time,action.id);const confirmed=this.db.prepare("SELECT action_type FROM engagement_actions WHERE post_id=? AND state='CONFIRMED'").all(post.id).map(x=>x.action_type),state=confirmed.includes('LIKE')&&confirmed.includes('INITIAL_REPLY')?'LIKED_AND_REPLIED':confirmed.includes('LIKE')?'LIKED':'REPLIED';this.db.prepare('UPDATE engagement_posts SET state=? WHERE id=?').run(state,post.id);this.db.prepare("UPDATE engagement_daily_slots SET state='CONSUMED',consumed_at=COALESCE(consumed_at,?) WHERE workspace=? AND group_id=? AND post_id=? AND state IN ('RESERVED','CONSUMED')").run(time,workspace,post.group_id,post.id);if(action.action_type==='INITIAL_REPLY')this.db.prepare('INSERT OR IGNORE INTO engagement_threads VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').run(randomUUID(),workspace,post.account_id,post.group_id,post.id,evidence.comment_id||null,0,'ACTIVE',null,time,time,time);this.event(workspace,'proactive_engagement_readback',{action_id:action.id,post_id:post.id,action:action.action_type});return this.proactiveAction(workspace,action.id)});}
